INSERT INTO feature VALUES('row-kind','types','Rows, one kind of labelled descriptions',NULL,'implemented','uncommon','mainstream languages','A row is a finite map from labels to entries, each label once and in no order of its own: a label written twice is refused, two rows defining one label apart do not join, and two rows listing the same entries in different orders are one row. The returner''s effect row is its first reading.','core-term surface-lowering','corpus/model/control/effect-rows.gandr corpus/pathological/control/effect-rows.gandr','corpus/model/control/effect-rows.gandr','#2273');
